DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('public.save_rental_order_amendment(uuid,integer,jsonb,text,timestamptz)'::regprocedure) INTO d;
d:=replace(d,'expected_total numeric; total numeric;', 'expected_total numeric; item_net numeric; item_vat numeric; addon_net numeric; cost_net numeric; total numeric;');
d:=regexp_replace(d,'SELECT round\(COALESCE\(sum[\s\S]*?IF abs\(expected_total-', E'SELECT COALESCE(sum(round((i->>\'quantity\')::numeric*(i->>\'unit_price\')::numeric*(1-COALESCE((i->>\'discount_percent\')::numeric,0)/100),2)),0), round(COALESCE(sum(round((i->>\'quantity\')::numeric*(i->>\'unit_price\')::numeric*(1-COALESCE((i->>\'discount_percent\')::numeric,0)/100),2)*COALESCE((i->>\'vat_rate\')::numeric,19)/100),0),2) INTO item_net,item_vat FROM jsonb_array_elements(_payload->\'items\') i;\nSELECT round(COALESCE(sum((a->>\'amount\')::numeric),0),2) INTO addon_net FROM jsonb_array_elements(_payload->\'items\') i CROSS JOIN LATERAL jsonb_array_elements(COALESCE(i->\'addons\',\'[]\'::jsonb)) a WHERE COALESCE((a->>\'optional\')::boolean,false)=false;\ncost_net:=COALESCE((_payload->>\'delivery_cost_delivery\')::numeric,0)+COALESCE((_payload->>\'delivery_cost_return\')::numeric,0)+COALESCE((_payload->>\'setup_cost\')::numeric,0)+COALESCE((_payload->>\'dismantle_cost\')::numeric,0)+COALESCE((_payload->>\'return_location_cost\')::numeric,0);\nexpected_total:=round(item_net+addon_net+cost_net,2)+round(item_vat+addon_net*0.19+cost_net*0.19,2);\nIF abs(expected_total-');
d:=replace(d,'numeric)>0.02','numeric)>0');
d:=replace(d,'result:=public.confirm_order', E'UPDATE public.b2b_reservations SET start_date=(SELECT start_date FROM public.rental_inquiries WHERE id=_id),end_date=(SELECT end_date FROM public.rental_inquiries WHERE id=_id),updated_at=now() WHERE inquiry_id=_id OR id=r.b2b_reservation_id;\nresult:=public.confirm_order');
EXECUTE d;
END $$;
CREATE FUNCTION public.guard_original_accepted_offer() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.original_accepted_offer IS NOT NULL AND NEW.original_accepted_offer IS DISTINCT FROM OLD.original_accepted_offer THEN RAISE EXCEPTION 'Ursprüngliches angenommenes Angebot ist unveränderlich'; END IF; RETURN NEW; END $$;
CREATE TRIGGER preserve_original_accepted_offer BEFORE UPDATE ON public.rental_inquiries FOR EACH ROW EXECUTE FUNCTION public.guard_original_accepted_offer();